def generate_test_cases(num_cases: int, seed: int = 42) -> list:
    import random
    from functools import lru_cache
    random.seed(seed)

    # Serialization helpers: input as comma‐separated numbers; output as a simple string
    def serialize_input(nums):
        return ",".join(str(x) for x in nums)

    def serialize_output(result):
        return str(result)

    # Sample solution (adapted from the provided sample) to compute expected output.
    def sample_solution(nums):
        N = len(nums)
        if len(set(nums)) == 1:
            return N // 2
        @lru_cache(maxsize=None)
        def rec(i, j, op):
            if j - i < 1:
                return 0
            mx = 0
            if nums[i] + nums[i+1] == op:
                mx = rec(i+2, j, op) + 1
            if nums[j] + nums[j-1] == op:
                mx = max(mx, rec(i, j-2, op) + 1)
            if nums[i] + nums[j] == op:
                mx = max(mx, rec(i+1, j-1, op) + 1)
            return mx
        mx = 0
        possible_ops = {nums[0] + nums[1], nums[0] + nums[-1], nums[-1] + nums[-2]}
        for op in possible_ops:
            mx = max(mx, rec(0, N-1, op))
        return mx

    # Predefined static test cases covering boundary, core, and special patterns.
    static_cases = [
        [1, 1],
        [1, 2],
        [5, 5, 5, 5],
        [3, 2, 1, 2, 3, 4],
        [3, 2, 6, 1, 4],
        [1, 2, 3, 4, 5, 6, 7, 8],
        [8, 7, 6, 5, 4, 3, 2, 1],
        [4, 9, 7, 9, 4],
        [1, 2, 1, 2, 1, 2, 1, 2],
    ]

    test_cases = []
    for case in static_cases:
        result = sample_solution(case)
        test_cases.append({
            "input": serialize_input(case),
            "output": serialize_output(result)
        })

    # If more test cases are desired, generate additional random cases.
    while len(test_cases) < num_cases:
        n = random.randint(2, 50)  # moderate size to avoid excessive recursion time
        nums = [random.randint(1, 20) for _ in range(n)]
        result = sample_solution(nums)
        test_cases.append({
            "input": serialize_input(nums),
            "output": serialize_output(result)
        })

    return test_cases[:num_cases]

# Example usage:
