def generate_test_cases(num_cases: int, seed: int = 42) -> list:
    import random
    random.seed(seed)

    # Helper: serialize input as "n1,n2,n3"
    def serialize_input(nums):
        return ",".join(map(str, nums))

    # Helper: serialize output (an integer) as string
    def serialize_output(result):
        return str(result)

    # Helper: sample solution using the provided sample solution logic
    def sample_solution(nums):
        n1, n2, n3 = nums
        b1, b2, b3 = n1.bit_length(), n2.bit_length(), n3.bit_length()
        return max(
            (n1 << (b2 + b3)) + (n2 << b3) + n3,
            (n1 << (b3 + b2)) + (n3 << b2) + n2,
            (n2 << (b1 + b3)) + (n1 << b3) + n3,
            (n2 << (b3 + b1)) + (n3 << b1) + n1,
            (n3 << (b1 + b2)) + (n1 << b2) + n2,
            (n3 << (b2 + b1)) + (n2 << b1) + n1
        )

    test_cases = []

    # Predefined fixed cases (diverse & boundary cases)
    fixed_cases = [
        [1, 2, 3],
        [2, 8, 16],
        [1, 1, 1],
        [127, 127, 127],
        [1, 127, 64],
        [3, 2, 1]
    ]

    cnt = 0
    for case in fixed_cases:
        if cnt >= num_cases:
            break
        expected = sample_solution(case)
        test_cases.append({
            "input": serialize_input(case),
            "output": serialize_output(expected)
        })
        cnt += 1

    # Generate additional random test cases if needed
    while cnt < num_cases:
        case = [random.randint(1, 127) for _ in range(3)]
        expected = sample_solution(case)
        test_cases.append({
            "input": serialize_input(case),
            "output": serialize_output(expected)
        })
        cnt += 1

    return test_cases

