def generate_test_cases(num_cases: int, seed: int = 42) -> list:
    import random
    random.seed(seed)
    MOD = 10**9 + 7

    # The sample solution is adapted from the provided solution.
    def sample_solution(s: str) -> int:
        n = len(s)
        mod = MOD

        def get(alice, bob):
            if alice == 'F' and bob == 'E':
                return -1
            if alice == 'F' and bob == 'W':
                return 1
            if alice == 'W' and bob == 'F':
                return -1
            if alice == 'W' and bob == 'E':
                return 1
            if alice == 'E' and bob == 'F':
                return 1
            if alice == 'E' and bob == 'W':
                return -1
            return 0

        dp = {}
        def func(prev, i, score):
            if score + (n - i) <= 0:
                return 0
            if i == n:
                return 1
            if (prev, i, score) in dp:
                return dp[(prev, i, score)]
            points = 0
            for x in "EFW":
                if x != prev:
                    d = get(s[i], x)
                    points += func(x, i + 1, score + d)
            dp[(prev, i, score)] = points % mod
            return dp[(prev, i, score)]
        return func('', 0, 0) % mod

    test_cases = []
    # Predefined test cases covering boundary, core, and edge cases.
    predefined = []
    predefined.append("F")         # Minimum length test case.
    predefined.append("FFF")       # Sample test case.
    predefined.append("FWEFW")     # Sample test case.
    predefined.append("EEEWFF")    # Custom pattern.
    predefined.append("WEWEWE")    # Alternating pattern.

    # Optionally include a stress test if sufficient test cases are requested.
    if num_cases > 7:
        stress = ''.join(random.choice("FWE") for _ in range(50))
        predefined.append(stress)

    # Use predefined test cases first.
    for s in predefined:
        if len(test_cases) >= num_cases:
            break
        try:
            expected = sample_solution(s)
        except Exception:
            expected = 0
        test_cases.append({
            "input": s,
            "output": str(expected)
        })

    # Generate additional random test cases if needed.
    while len(test_cases) < num_cases:
        length = random.randint(3, 20)
        s = ''.join(random.choice("FWE") for _ in range(length))
        try:
            expected = sample_solution(s)
        except Exception:
            expected = 0
        test_cases.append({
            "input": s,
            "output": str(expected)
        })

    return test_cases

