def generate_test_cases(num_cases: int, seed: int = 42) -> list[dict]:
    import random
    random.seed(seed)

    def serialize_points(points):
        # Serialize the list of points as "x,y;x,y;..."
        return ';'.join(f"{x},{y}" for x, y in points)

    def sample_solution(points):
        pt_indices = [None, None, None, None]
        min_mh_sums = [float('inf'), float('inf')]
        min_mh_diff = [float('inf'), float('inf')]
        max_mh_sums = [float('-inf'), float('-inf')]
        max_mh_diff = [float('-inf'), float('-inf')]
        answer = float('inf')
        for point_index, point in enumerate(points): 
            point_sum = point[0] + point[1]
            point_diff = point[0] - point[1]
            # Update for Manhattan sums
            if point_sum < min_mh_sums[0]:
                pt_indices[0] = point_index
                min_mh_sums[1] = min_mh_sums[0]
                min_mh_sums[0] = point_sum
            elif point_sum < min_mh_sums[1]:
                min_mh_sums[1] = point_sum

            if point_sum > max_mh_sums[0]:
                pt_indices[1] = point_index
                max_mh_sums[1] = max_mh_sums[0]
                max_mh_sums[0] = point_sum
            elif point_sum > max_mh_sums[1]:
                max_mh_sums[1] = point_sum 

            # Update for Manhattan differences
            if point_diff < min_mh_diff[0]:
                pt_indices[2] = point_index
                min_mh_diff[1] = min_mh_diff[0]
                min_mh_diff[0] = point_diff
            elif point_diff < min_mh_diff[1]:
                min_mh_diff[1] = point_diff

            if point_diff > max_mh_diff[0]:
                pt_indices[3] = point_index
                max_mh_diff[1] = max_mh_diff[0]
                max_mh_diff[0] = point_diff
            elif point_diff > max_mh_diff[1]:
                max_mh_diff[1] = point_diff

        for pt_index in pt_indices: 
            if pt_index is None:
                continue
            if pt_index == pt_indices[0]:
                min_mh_sum_val = min_mh_sums[1]
            else:
                min_mh_sum_val = min_mh_sums[0]
            if pt_index == pt_indices[1]:
                max_mh_sum_val = max_mh_sums[1]
            else:
                max_mh_sum_val = max_mh_sums[0]
            if pt_index == pt_indices[2]:
                min_mh_dif_val = min_mh_diff[1]
            else:
                min_mh_dif_val = min_mh_diff[0]
            if pt_index == pt_indices[3]:
                max_mh_dif_val = max_mh_diff[1]
            else:
                max_mh_dif_val = max_mh_diff[0]
            candidate = max(max_mh_sum_val - min_mh_sum_val, max_mh_dif_val - min_mh_dif_val)
            answer = min(answer, candidate)
        return int(answer)

    test_cases = []

    # Category 1: All points are identical (edge case)
    points = [[1, 1], [1, 1], [1, 1]]
    expected = sample_solution(points)
    test_cases.append({
        "input": serialize_points(points),
        "output": str(expected)
    })

    # Category 2: Three distinct points
    points = [[1, 2], [2, 3], [3, 4]]
    expected = sample_solution(points)
    test_cases.append({
        "input": serialize_points(points),
        "output": str(expected)
    })

    # Category 3: Small random case (n = 5)
    points = []
    for _ in range(5):
        x = random.randint(1, 100)
        y = random.randint(1, 100)
        points.append([x, y])
    expected = sample_solution(points)
    test_cases.append({
        "input": serialize_points(points),
        "output": str(expected)
    })

    # Category 4: Points on a horizontal line
    n = 10
    points = [[i, 50] for i in range(1, n + 1)]
    expected = sample_solution(points)
    test_cases.append({
        "input": serialize_points(points),
        "output": str(expected)
    })

    # Category 5: Points on a vertical line
    n = 10
    points = [[50, i] for i in range(1, n + 1)]
    expected = sample_solution(points)
    test_cases.append({
        "input": serialize_points(points),
        "output": str(expected)
    })

    # Category 6: Additional random cases to reach num_cases
    while len(test_cases) < num_cases:
        n = random.randint(3, 20)
        points = []
        for _ in range(n):
            x = random.randint(1, 10**8)
