    def sample_solution(strength, k):
        n = len(strength)

        @lru_cache(maxsize=None)
        def minTime(x, mask):
            if mask.bit_count() == n:
                return 0
            times = []
            for i, s in enumerate(strength):
                if mask & (1 << i):
                    continue
                times.append(ceil(s / x) + minTime(x + k, mask | (1 << i)))
            return min(times)

        return minTime(1, 0)

