def generate_test_cases(num_cases: int, seed: int = 42) -> list[dict]:
    import random
    random.seed(seed)

    # Sample solution as given in the problem description
    def sample_solution(nums, k):
        if k == 1:
            return nums[:]
        n = len(nums)
        res = [-1] * (n - k + 1)
        i = 0
        while i < n:
            j = i + 1
            while j < n and nums[j] == nums[j - 1] + 1:
                j += 1
                if j - i >= k:
                    res[j - k] = nums[j - 1]
            i = j
        return res

    # Helper to serialize the input and output in a simple string format.
    def serialize_input(nums, k):
        return ",".join(str(x) for x in nums) + " " + str(k)

    def serialize_output(result):
        return ",".join(str(x) for x in result)

    test_cases = []
    # Predefined fixed test cases (cover various edge cases)
    fixed_cases = [
        ([7], 1),                              # Single element, k = 1
        ([1, 2, 3, 4, 5], 3),                    # Fully consecutive sorted sequence
        ([4, 2, 8, 3], 2),                       # No consecutive ascending sequence
        ([1, 2, 3, 4, 3, 2, 5], 3),              # Mixed case from sample
        ([2, 2, 2, 2, 2], 4),                    # All same elements
        ([3, 2, 3, 2, 3, 2], 2)                  # Alternating pattern
    ]

    for nums, k in fixed_cases:
        if len(test_cases) >= num_cases:
            break
        expected = sample_solution(nums, k)
        test_cases.append({
            "input": serialize_input(nums, k),
            "output": serialize_output(expected)
        })

    # Generate additional random test cases if needed
    while len(test_cases) < num_cases:
        # Randomly decide on the size of the array (stress tests occasionally)
        if random.random() < 0.2:
            n = random.randint(20, 500)
        else:
            n = random.randint(1, 15)
        k = random.randint(1, n)
        r = random.random()
        if r < 0.3:
            # Fully consecutive ascending sequence
            start = random.randint(1, 50)
            nums = [start + i for i in range(n)]
        elif r < 0.6:
            # Partly consecutive: each next element has a 70% change to be previous+1
            nums = [random.randint(1, 100)]
            for _ in range(1, n):
                if random.random() < 0.7:
                    nums.append(nums[-1] + 1)
                else:
                    # Ensure not consecutively continuing
                    candidate = random.randint(1, 100)
                    while candidate == nums[-1] + 1:
                        candidate = random.randint(1, 100)
                    nums.append(candidate)
        else:
            # Fully random numbers
            nums = [random.randint(1, 100) for _ in range(n)]
        expected = sample_solution(nums, k)
        test_cases.append({
            "input": serialize_input(nums, k),
            "output": serialize_output(expected)
        })

    return test_cases

