def generate_test_cases(num_cases: int, seed: int = 42) -> list:
    import random
    random.seed(seed)
    test_cases = []

    def mat_mul(mat1, mat2, mod):
        n = len(mat1)
        m = len(mat2)
        p = len(mat2[0])
        res = [[0] * p for _ in range(n)]
        for i in range(n):
            for j in range(p):
                s_val = 0
                for k in range(m):
                    s_val += mat1[i][k] * mat2[k][j]
                res[i][j] = s_val % mod
        return res

    def mat_pow(mat, n, mod):
        size = len(mat)
        res = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
        while n > 0:
            if n & 1:
                res = mat_mul(res, mat, mod)
            mat = mat_mul(mat, mat, mod)
            n //= 2
        return res

    def sample_solution(s, t, A):
        mod = 10**9 + 7
        M = [[0] * 26 for _ in range(26)]
        for i, k in enumerate(A):
            for j in range(1, k + 1):
                M[i][(i + j) % 26] = 1
        Mt = mat_pow(M, t, mod)
        count = [0] * 26
        for c in s:
            count[ord(c) - ord('a')] += 1
        res = mat_mul([count], Mt, mod)
        return sum(res[0]) % mod

    for i in range(num_cases):
        if i == 0:
            s = "abcyy"
            t_val = 2
            A = [1] * 25 + [2]
        elif i == 1:
            s = "azbk"
            t_val = 1
            A = [2] * 26
        else:
            prob = random.random()
            if prob < 0.1:
                length = 1
            elif prob < 0.2:
                length = random.randint(10000, 100000)
            else:
                length = random.randint(2, 100)
            s = "".join(random.choice("abcdefghijklmnopqrstuvwxyz") for _ in range(length))
            t_val = 10**9 if random.random() < 0.1 else random.randint(1, 1000)
            if random.random() < 0.1:
                val = random.randint(1, 25)
                A = [val] * 26
            else:
                A = [random.randint(1, 25) for _ in range(26)]
        # Serialization format: "<s> <t> <num0,num1,...,num25>"
        test_input = f"{s} {t_val} " + ",".join(str(num) for num in A)
        expected_output = str(sample_solution(s, t_val, A))
        test_cases.append({"input": test_input, "output": expected_output})
    return test_cases

