    import random
    from collections import defaultdict
    from functools import lru_cache

    random.seed(seed)

    def serialize_grid(grid):
        # Serialize a 2D grid into a string where each row is comma‐separated and rows are separated by semicolons.
        return ";".join([",".join(map(str, row)) for row in grid])

    def sample_solution(grid):
        # Adapted sample solution from the provided sample code.
        d = defaultdict(int)
        for i, row in enumerate(grid):
            bit = (1 << i)
            for v in row:
                d[v] |= bit
        items = sorted(d.items(), reverse=True)

        @lru_cache(maxsize=None)
        def dp(i, mask):
            if i == len(items):
                return 0
            v, m = items[i]
            ans = 0
            m_copy = m
            j = 0
            while m_copy:
                if m_copy & 1:
                    if not (mask & (1 << j)):
                        ans = max(ans, v + dp(i + 1, mask | (1 << j)))
                m_copy //= 2
                j += 1
            if ans == 0:
                ans = dp(i + 1, mask)
            return ans

        return dp(0, 0)

    test_cases = []
    fixed_tests = []

    # Fixed test cases
    fixed_tests.append([[1]])                                   # Minimal grid: 1x1
    fixed_tests.append([[1, 2, 3, 4]])                          # Single row, multiple columns
    fixed_tests.append([[1, 2, 3], [4, 3, 2], [1, 1, 1]])        # Sample case 1
    fixed_tests.append([[8, 7, 6], [8, 3, 2]])                  # Sample case 2
    fixed_tests.append([[5, 5], [5, 5]])                        # All same values (only one can be selected)
    fixed_tests.append([[random.randint(1, 100) for _ in range(10)] for _ in range(10)])  # 10x10 grid

    grids = []
    if num_cases <= len(fixed_tests):
        grids = fixed_tests[:num_cases]
    else:
        grids.extend(fixed_tests)
        for _ in range(num_cases - len(fixed_tests)):
            r = random.randint(1, 10)
            c = random.randint(1, 10)
            grid = [[random.randint(1, 100) for _ in range(c)] for _ in range(r)]
            grids.append(grid)

    for grid in grids:
        inp = serialize_grid(grid)
        expected = sample_solution(grid)
        test_cases.append({"input": inp, "output": str(expected)})

    return test_cases

