def generate_test_cases(num_cases: int, seed: int = 42) -> list[dict]:
    import random
    random.seed(seed)

    def sample_solution(nums, target):
        inc = 0
        dec = 0
        ops = 0
        for i in range(len(nums)):
            diff = target[i] - nums[i]
            if diff > 0:
                if diff > inc:
                    ops += diff - inc
                inc = diff
                dec = 0
            elif diff < 0:
                if diff < dec:
                    ops += dec - diff
                dec = diff
                inc = 0
            else:
                inc = 0
                dec = 0
        return ops

    def serialize_input(nums, target):
        # Format: comma-separated integers for nums, a space, then comma-separated integers for target.
        return "{} {}".format(",".join(map(str, nums)), ",".join(map(str, target)))

    def serialize_output(result):
        return str(result)

    # Fixed test cases to cover common, edge, and provided examples.
    fixed_cases = [
        ([1], [1]),
        ([1], [5]),
        ([3, 5, 1, 2], [4, 6, 2, 4]),
        ([1, 3, 2], [2, 1, 4]),
    ]
    cases = []
    # Use fixed cases first.
    for i in range(min(num_cases, len(fixed_cases))):
        nums, target = fixed_cases[i]
        inp = serialize_input(nums, target)
        out = serialize_output(sample_solution(nums, target))
        cases.append({"input": inp, "output": out})

    # Generate additional random test cases if needed.
    while len(cases) < num_cases:
        # 20% chance for a stress test with larger array lengths
        if random.random() < 0.2:
            length = random.choice([50, 100, 1000, 100000])
        else:
            length = random.randint(1, 20)
        # Use a larger numeric range for longer arrays.
        if length < 50:
            low, high = 1, 100
        else:
            low, high = 1, 10**8
        nums = [random.randint(low, high) for _ in range(length)]
        target = [random.randint(low, high) for _ in range(length)]
        inp = serialize_input(nums, target)
        out = serialize_output(sample_solution(nums, target))
        cases.append({"input": inp, "output": out})
    return cases

