def generate_test_cases(num_cases: int, seed: int = 42) -> list:
    import random
    import heapq

    def serialize_input(nums, changeIndices):
        return ",".join(map(str, nums)) + " " + ",".join(map(str, changeIndices))

    def serialize_output(result):
        return str(result)

    def sample_solution(nums, changeIndices):
        lookup = [-1] * len(nums)
        for i in reversed(range(len(changeIndices))):
            if nums[changeIndices[i] - 1]:
                lookup[changeIndices[i] - 1] = i
        total = sum(nums) + len(nums)
        left = sum((1 if lookup[i] != -1 else nums[i]) for i in range(len(nums))) + len(nums)
        right = len(changeIndices)
        def check(t):
            min_heap = []
            cnt = 0
            for i in reversed(range(t)):
                if i != lookup[changeIndices[i] - 1]:
                    cnt += 1
                    continue
                heapq.heappush(min_heap, nums[changeIndices[i] - 1])
                if cnt:
                    cnt -= 1
                else:
                    cnt += 1
                    heapq.heappop(min_heap)
            return total - (sum(min_heap) + len(min_heap)) <= cnt
        while left <= right:
            mid = left + (right - left) // 2
            if check(mid):
                right = mid - 1
            else:
                left = mid + 1
        return left if left <= len(changeIndices) else -1

    random.seed(seed)
    test_cases = []

    # Fixed test cases covering boundary and example scenarios.
    fixed = [
        ([0], [1]),  # Minimal case: one element.
        ([3, 2, 3], [1, 3, 2, 2, 2, 2, 3]),  # Example 1.
        ([0, 0, 1, 2], [1, 2, 1, 2, 1, 2, 1, 2]),  # Example 2.
        ([1, 2, 3], [1, 2, 3])  # Example 3.
    ]

    for nums, changeIndices in fixed:
        if len(test_cases) >= num_cases:
            break
        inp = serialize_input(nums, changeIndices)
        outp = serialize_output(sample_solution(nums, changeIndices))
        test_cases.append({"input": inp, "output": outp})

    # Generate additional random test cases to reach the desired count.
    while len(test_cases) < num_cases:
        n = random.randint(1, 10)
        m = random.randint(1, 10)
        nums = [random.randint(0, 10) for _ in range(n)]
        changeIndices = [random.randint(1, n) for _ in range(m)]
        inp = serialize_input(nums, changeIndices)
        outp = serialize_output(sample_solution(nums, changeIndices))
        test_cases.append({"input": inp, "output": outp})

    return test_cases

