def generate_test_cases(num_cases: int, seed: int = 42) -> list:
    import random
    random.seed(seed)

    # Provided sample solution adapted for computing expected outputs.
    def sample_solution(rewardValues):
        vals = sorted(set(rewardValues))
        if not vals:
            return 0
        def helper(idx, rmax):
            res = 0
            for i in range(idx - 1, -1, -1):
                if vals[i] > rmax:
                    continue
                nrmax = min(rmax - vals[i], vals[i] - 1)
                if nrmax + vals[i] <= res:
                    break
                res = max(res, vals[i] + helper(i, nrmax))
            return res
        return vals[-1] + helper(len(vals) - 1, vals[-1] - 1)

    # Define several case generators to cover different test categories.
    def gen_single():
        return [1]

    def gen_ex1():
        return [1, 1, 3, 3]

    def gen_ex2():
        return [1, 6, 4, 3, 2]

    def gen_sorted():
        n = random.randint(5, 15)
        return sorted([random.randint(1, 50) for _ in range(n)])

    def gen_reverse_sorted():
        n = random.randint(5, 15)
        return sorted([random.randint(1, 50) for _ in range(n)], reverse=True)

    def gen_random_duplicates():
        n = random.randint(5, 20)
        return [random.randint(1, 10) for _ in range(n)]

    def gen_random():
        n = random.randint(5, 30)
        return [random.randint(1, 500) for _ in range(n)]

    def gen_stress():
        # Stress test with many elements but with limited unique values.
        n = random.randint(1000, 5000)
        return [random.randint(1, 50) for _ in range(n)]

    def gen_increasing():
        n = random.randint(5, 20)
        a = random.randint(1, 10)
        arr = []
        for _ in range(n):
            arr.append(a)
            a += random.randint(1, 5)
        return arr

    generators = [gen_single, gen_ex1, gen_ex2, gen_sorted, gen_reverse_sorted,
                  gen_random_duplicates, gen_random, gen_stress, gen_increasing]

    test_cases = []
    for i in range(num_cases):
        # Cycle through our generator functions.
        arr = generators[i % len(generators)]()
        # Serialize the input as a simple comma-separated list.
        input_str = ",".join(map(str, arr))
        # Compute expected output using the provided sample solution.
        expected = sample_solution(arr)
        test_cases.append({
            "input": input_str,
            "output": str(expected)
        })
    return test_cases

